{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE spfclaims_final_new_spf_table_c AS WITH base AS ( SELECT *, CASE WHEN UPPER(TRIM(channel_name)) IN (\'SHOPIFY\', \'B2C-DELHIVERY\', \'B2C-PROZO\', \'B2C-EKART\', \'B2C PROZO\', \'B2C-BLUEDART\', \'B2C-BLITZ\') THEN \'SHOPIFY\' WHEN UPPER(TRIM(channel_name)) IN (\'SAPL_AJIO_OMNI_2\', \'SAPL_AJIO_OMNI_EMIZA\', \'SAPL_AJIO_OMNI\', \'AJIO\', \'MP_AJIO\') THEN \'AJIO\' WHEN UPPER(TRIM(channel_name)) IN (\'FLIPKART_SAPLWH2\', \'FLIPKART_SAPL\', \'FLIPKART\', \'MP-FLIPKART\', \'FLIPKART_SAPL_EMIZA\') THEN \'FLIPKART\' WHEN UPPER(TRIM(channel_name)) IN (\'MYNTRAPMP_SAPL-WH2\', \'SAPL_MYNTAPPMP\', \'SAPL_MYNTRAPPMP\', \'MP-MYNTRA\', \'SAPL_MYNTAPP_EMIZA\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA_EMIZA\', \'MYNTRA\') THEN \'MYNTRA\' WHEN UPPER(TRIM(channel_name)) IN (\'AMAZON_FLEX_WH2\', \'AMAZON_FLEX_API_SAPL\', \'MP-AMAZON\', \'AMAZON\') THEN \'AMAZON\' WHEN UPPER(TRIM(channel_name)) IN (\'MP-NYKAA\', \'NYKAA_FASHION_WH2\', \'NYKAA_FASHION_WH\', \'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA\') THEN \'NYKAA\' WHEN UPPER(TRIM(channel_name)) = \'MP-CRED\' THEN \'CRED\' WHEN UPPER(TRIM(channel_name)) = \'GROO SHIP\' THEN \'GROO SHIP\' WHEN UPPER(TRIM(channel_name)) = \'DONOSHOP\' THEN \'DONOSHOP\' WHEN UPPER(TRIM(channel_name)) = \'BLUEDART\' THEN \'BLUEDART\' WHEN UPPER(TRIM(channel_name)) = \'SELFSHIP\' THEN \'SELFSHIP\' ELSE UPPER(TRIM(channel_name)) END AS cleaned_channel_name FROM spf_fact_items_final_spf_table WHERE received_date NOT IN (\'\', \'null\') ), cleaned AS ( SELECT CASE WHEN TRIM(CAST(b.ID AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE b.ID END AS ID, TRY_TO_DATE(NULLIF(NULLIF(b.month, \'\'), \'null\'), \'DD-MM-YYYY\') AS month, TRY_TO_NUMBER(NULLIF(NULLIF(b.AGEING, \'\'), \'null\')) AS AGEING, NULLIF(NULLIF( CASE WHEN UPPER(TRIM(b.DONE_BY)) IN (\'PRADEEP\',\'P\') THEN \'PRADEEP\' WHEN UPPER(TRIM(b.DONE_BY)) IN (\'BAJARANGI\',\'B\') THEN \'BAJARANGI\' WHEN UPPER(TRIM(b.DONE_BY)) IN (\'RAMYA\',\'R\') THEN \'RAMYA\' WHEN UPPER(REPLACE(TRIM(b.DONE_BY),\'’\',\'\')) IN (\'CHANDAN\',\'C\') THEN \'CHANDAN\' WHEN UPPER(REPLACE(TRIM(b.DONE_BY),\'✓\',\'\')) IN (\'DHYAN\',\'D\') THEN \'DHYAN\' ELSE TRIM(b.DONE_BY) END, \'\'), \'null\') AS DONE_BY, NULLIF(NULLIF(b.REMARKS, \'\'), \'null\') AS REMARKS, NULLIF(NULLIF(b.WH_TYPE, \'\'), \'null\') AS WH_TYPE, CASE WHEN TRIM(CAST(b.TOTAL_QTY AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE b.TOTAL_QTY END AS TOTAL_QTY, NULLIF(NULLIF(b.CREATED_BY, \'\'), \'null\') AS CREATED_BY, NULLIF(NULLIF(b.qc_comment, \'\'), \'null\') AS qc_comment, CASE WHEN b.qc_comment IS NULL OR LOWER(TRIM(b.qc_comment)) IN (\'\', \'null\') THEN NULL WHEN LOWER(b.qc_comment) LIKE \'%washing%\' OR LOWER(b.qc_comment) LIKE \'%wash%\' THEN \'Good Inventory\' WHEN LOWER(b.qc_comment) LIKE \'%fake%\' THEN \'Fake\' WHEN LOWER(b.qc_comment) LIKE \'%wpr%\' OR LOWER(b.qc_comment) LIKE \'%wrong%\' THEN \'WPR\' WHEN LOWER(b.qc_comment) LIKE \'%damage%\' OR LOWER(b.qc_comment) LIKE \'%damag%\' THEN \'Damage\' WHEN LOWER(b.qc_comment) LIKE \'%missing%\' OR LOWER(b.qc_comment) LIKE \'%empty%\' THEN \'Missing\' WHEN LOWER(b.qc_comment) LIKE \'%partial%\' THEN \'Partial Returns\' ELSE NULL END AS qc_bucket, b.cleaned_channel_name AS channel_name, UPPER(NULLIF(NULLIF(b.tracking_no, \'\'), \'null\')) AS tracking_no, NULLIF(NULLIF(b.item_skucode, \'\'), \'null\') AS item_skucode, NULLIF(NULLIF(b.PHY_SKU_CODE, \'\'), \'null\') AS PHY_SKU_CODE, NULLIF(NULLIF(b.PUTAWAY_CODE, \'\'), \'null\') AS PUTAWAY_CODE, COALESCE( TRY_TO_DATE(NULLIF(NULLIF(b.QC_DONE_DATE, \'\'), \'null\'), \'DD-MM-YYYY\'), CAST( COALESCE( TRY_TO_TIMESTAMP_NTZ(NULLIF(NULLIF(r.QC_TIMESTAMP, \'\'), \'null\'), \'MON DD, YYYY HH12:MI AM\'), TRY_TO_TIMESTAMP_NTZ(NULLIF(NULLIF(r.QC_TIMESTAMP, \'\'), \'null\'), \'MON DD YYYY HH12:MI AM\') ) AS DATE ) ) AS QC_DONE_DATE, NULLIF(NULLIF(b.QC_VIDEO_LINK, \'\'), \'null\') AS QC_VIDEO_LINK, TRY_TO_DATE(NULLIF(NULLIF(b.received_date, \'\'), \'null\'), \'DD-MM-YYYY\') AS received_date, NULLIF(NULLIF(b.shipment_type, \'\'), \'null\') AS shipment_type, NULLIF(NULLIF(b.ticket_number, \'\'), \'null\') AS ticket_number, COALESCE( TRY_TO_DATE(NULLIF(NULLIF(b.ticket_raised_date, \'\'), \'null\'), \'DD-MM-YYYY\'), CAST(TRY_TO_TIMESTAMP(NULLIF(NULLIF(b.ticket_raised_date, \'\'), \'null\'), \'MON DD, YYYY HH12:MI AM\') AS DATE) ) AS ticket_raised_date, NULLIF(NULLIF(b.ticket_status, \'\'), \'null\') AS ticket_status, LOWER(TRIM(REGEXP_REPLACE(REPLACE(b.ticket_status, CHR(160), \' \'), \'\\s+\', \' \'))) AS cleaned_status, NULLIF(NULLIF(b.SALE_ORDER_CODE, \'\'), \'null\') AS SALE_ORDER_CODE, NULLIF(NULLIF(b.REJECTION_REASON, \'\'), \'null\') AS REJECTION_REASON, NULLIF(NULLIF(b.TICKET_RAISED_BY, \'\'), \'null\') AS TICKET_RAISED_BY, CASE WHEN TRIM(CAST(b.LAST_UPDATED_AT AS TEXT)) IN (\'\', \'null\') THEN NULL ELSE b.LAST_UPDATED_AT END AS LAST_UPDATED_AT, TO_TIMESTAMP(CAST(FLOOR(b.LAST_UPDATED_AT / 1000) AS NUMBER)) AS last_updated_at_readable, NULLIF(NULLIF(CONCAT_WS(\'_\', b.tracking_no, b.item_skucode), \'\'), \'null\') AS CONCATE1, CASE WHEN LOWER(b.remarks) IN (\'not eligible\',\'emiza shipment\') THEN \'Not Eligible\' WHEN LOWER(b.created_by) IN (\'emiza1@snich.club\', \'emiza2@snitch.club\') THEN \'Not Eligible\' WHEN (LOWER(b.cleaned_channel_name) = \'flipkart\' AND LOWER(b.qc_comment) LIKE ANY (\'%wpr%\',\'%damage%\',\'%missing%\',\'%wrong product%\') AND LOWER(b.qc_comment) NOT LIKE \'%partial%\') THEN \'Not Eligible\' WHEN (LOWER(b.cleaned_channel_name) = \'shopify\' AND LOWER(b.qc_comment) LIKE \'%fake%\') THEN \'Eligible\' WHEN LOWER(b.cleaned_channel_name) = \'shopify\' THEN \'Not Eligible\' ELSE \'Eligible\' END AS eligible_to_raise_flag FROM base b LEFT JOIN return_2_inwarding_data r ON b.tracking_no = r.AWB_no AND r.QC_TIMESTAMP IS NOT NULL AND r.QC_TIMESTAMP != \'\' ), latest_status AS ( SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER ( PARTITION BY tracking_no, item_skucode ORDER BY last_updated_at DESC ) = 1 ), gs_dedup AS ( SELECT UPPER(\"Tracking No\") AS tracking_no, MAX(CASE WHEN LOWER(main) IN (\'raised\',\'yes\',\'y\',\'true\') THEN 1 ELSE 0 END) AS gs_ticket_flag, MAX(CASE WHEN LOWER(main) = \'not eligible\' THEN \'Not Eligible\' ELSE NULL END) AS gs_eligible_flag FROM gs_bad_sheet1_final WHERE main IS NOT NULL GROUP BY UPPER(\"Tracking No\") ), external_tracking AS ( SELECT DISTINCT UPPER(awb) AS tracking_no FROM spf_b2c_final WHERE awb IS NOT NULL UNION SELECT DISTINCT UPPER(trackingid) FROM spf_mp_final WHERE trackingid IS NOT NULL UNION SELECT DISTINCT UPPER(returntrackingid) FROM spf_mp_final WHERE returntrackingid IS NOT NULL ) SELECT ls.* EXCLUDE (eligible_to_raise_flag), CASE WHEN gs.gs_ticket_flag = 1 THEN 1 WHEN et.tracking_no IS NOT NULL THEN 1 WHEN lower(ls.REMARKS) = \'raised\' THEN 1 WHEN ls.ticket_number IS NOT NULL AND ls.ticket_number != \'Not Eligible\' THEN 1 WHEN ls.ticket_raised_date IS NOT NULL THEN 1 WHEN LOWER(TRIM(ls.ticket_status)) IN ( \'claim accepted\',\'claim denied\',\'pending\',\'accept\',\'approved\', \'dispute accepted\',\'payment completed\',\'reject\',\'rejected\', \'dispute not accepted\',\'not approved\',\'raised within tat\', \'under investigation\',\'open\',\'awaiting seller response\' ) THEN 1 ELSE 0 END AS ticket_raised_flag, CASE WHEN gs.gs_eligible_flag = \'Not Eligible\' THEN \'Not Eligible\' WHEN ( CASE WHEN gs.gs_ticket_flag = 1 THEN 1 WHEN et.tracking_no IS NOT NULL THEN 1 ELSE 0 END ) = 1 AND ls.eligible_to_raise_flag = \'Not Eligible\' THEN \'Eligible\' ELSE ls.eligible_to_raise_flag END AS eligible_to_raise_flag, CASE WHEN LOWER(ls.cleaned_status) IN (\'accept\',\'accepted\',\'approved\',\'approval\',\'dispute accepted\',\'claim accepted\',\'payment completed\',\'payment_completed\') THEN \'Approved\' WHEN LOWER(ls.cleaned_status) IN (\'claim denied\',\'reject\',\'rejected\',\'dispute not accepted\',\'not approved\',\'already tat breached\',\'closed-no response\') THEN \'Rejected\' WHEN LOWER(ls.cleaned_status) IN (\'raised within tat\',\'raised\',\'under investigation\',\'open\',\'awaiting seller response\',\'awaiting_agent_response\',\'pending from snitch team\') THEN \'Under Investigation\' WHEN LOWER(ls.cleaned_status) IN (\'to be raised\',\'nf\',\'o\',\'#na\',\'#n/a\',\'pending\',\'0\',\'not available\') THEN \'Pending\' ELSE \'Unknown\' END AS ticket_status_bucket FROM latest_status ls LEFT JOIN gs_dedup gs ON ls.tracking_no = gs.tracking_no LEFT JOIN external_tracking et ON ls.tracking_no = et.tracking_no;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            